'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const schemas={jobs:{label:'キャラクター・職業',fields:['member','name','job','level','role','cost','colors','colorBonus','attack','magic','heal','hp','speed']},gear:{label:'装備',fields:['name','slot','role','element','count','minLevel','jobs','attack','magic','heal','hp','speed']},hearts:{label:'こころ',fields:['name','rank','color','cost','costBonus','count','attack','magic','heal','hp','speed']}};
const labels={member:'キャラ番号（1〜4）',name:'名前',job:'職業',level:'レベル',role:'役割',cost:'こころコスト',colors:'枠色（/区切り）',colorBonus:'色一致倍率',attack:'攻撃評価値',magic:'呪文評価値',heal:'回復評価値',hp:'HP',speed:'すばやさ',slot:'部位',element:'属性',count:'所持数',minLevel:'必要レベル',jobs:'使用可能職業（/区切り・*で全職）',rank:'ランク',color:'色',costBonus:'最大コスト加算'};
const choices={role:['物理','呪文','回復'],slot:['武器','盾','頭','体上','体下','アクセサリー'],element:['無','メラ','ヒャド','イオ','バギ','デイン','ドルマ','ジバリア','ギラ'],color:['赤','黄','青','紫','緑','白']};
const numeric=new Set(['member','level','cost','colorBonus','attack','magic','heal','hp','speed','count','minLevel','costBonus']);
const uid=()=>crypto.randomUUID();
function sample(){let jobs=[];for(let i=1;i<=4;i++)for(const [j,r,lv]of [['攻撃職サンプル','物理',65],['魔法職サンプル','呪文',60],['回復職サンプル','回復',55]])jobs.push({id:uid(),member:i,name:'キャラ'+i,job:j,level:lv+i,role:r,cost:400,colors:'虹/赤+紫/黄+緑/青+緑',colorBonus:1.2,attack:r==='物理'?220:80,magic:r==='呪文'?240:50,heal:r==='回復'?230:30,hp:450,speed:230+i*10});return {jobs,gear:[['練習用の炎の剣','物理','メラ',180,0,0,2],['練習用の氷の杖','呪文','ヒャド',0,190,0,1],['練習用の回復杖','回復','無',0,0,200,2],['練習用の無属性剣','物理','無',200,0,0,1]].map(([name,role,element,attack,magic,heal,count])=>({id:uid(),name,slot:'武器',role,element,attack,magic,heal,count,jobs:'*',minLevel:1,hp:0,speed:0})),hearts:Array.from({length:8},(_,i)=>({id:uid(),name:'練習用こころ'+(i+1),rank:'S',color:['赤','紫','緑','黄'][i%4],cost:70+i*5,costBonus:4,count:2,attack:i%4===0?65:15,magic:i%4===1?70:10,heal:i%4===2?65:5,hp:40+i*4,speed:20+i*2}))};}
let data;try{data=JSON.parse(localStorage.getItem('walk-lab-v1'));if(!data||!['jobs','gear','hearts'].every(k=>Array.isArray(data[k])))throw Error();}catch{data=sample();}
let tab='legacy/battle',results=null;const target={mode:'ボス',healers:1,minHp:500,minSpeed:0,weakness:Object.fromEntries(choices.element.map(e=>[e,1]))};
function save(){localStorage.setItem('walk-lab-v1',JSON.stringify(data));results=null;}
function msg(text){$('#message').textContent=text;}
function field(key,value=''){if(choices[key])return `<label>${labels[key]}<select name="${key}">${choices[key].map(v=>`<option ${v===value?'selected':''}>${v}</option>`).join('')}</select></label>`;return `<label>${labels[key]}<input name="${key}" ${numeric.has(key)?'type="number" min="0" step="any"':''} value="${esc(value)}" required></label>`;}
function render(){ $('#tabs').innerHTML=[['legacy/battle','行動計画'],['catalog','コンテンツ・最新データ'],['plan','簡易編成（旧試作）'],['jobs','キャラクター・職業'],['gear','所持装備'],['hearts','所持こころ'],['transfer','CSV・バックアップ'],['help','計算のしくみ']].map(([k,t])=>`<button data-tab="${k}" class="${k===tab?'active':''}">${t}</button>`).join('');$('#tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;msg('');render();});if(tab==='battle')renderBattle();else if(tab==='catalog')renderCatalog();else if(tab==='plan')renderPlan();else if(schemas[tab])renderData();else if(tab==='transfer')renderTransfer();else renderHelp();}
function renderPlan(){ $('#view').innerHTML=`<div class="metrics"><div><b>4</b><span class="muted">キャラクター</span></div><div><b>${data.gear.reduce((n,x)=>n+Number(x.count),0)}</b><span class="muted">所持装備</span></div><div><b>${data.hearts.reduce((n,x)=>n+Number(x.count),0)}</b><span class="muted">所持こころ</span></div></div><div class="layout"><form id="conditions" class="panel stack"><h2>攻略条件</h2><label>コンテンツ・評価の目的<select name="mode">${['ボス','周回','耐久'].map(x=>`<option ${x===target.mode?'selected':''}>${x}</option>`).join('')}</select></label><label>回復役の最低人数<input name="healers" type="number" min="0" max="4" value="${target.healers}" required></label><label>各キャラの最低HP<input name="minHp" type="number" min="0" value="${target.minHp}" required></label><label>各キャラの最低すばやさ<input name="minSpeed" type="number" min="0" value="${target.minSpeed}" required></label><details><summary>敵の属性倍率を設定</summary><p class="muted">弱点は1より大きく、耐性は1未満。敵ごとに入力してください。</p><div class="fields">${choices.element.map(e=>`<label>${e}<input name="weak-${e}" type="number" min="0" step="0.05" value="${target.weakness[e]}" required></label>`).join('')}</div></details><button class="primary" type="submit">編成候補を算出する →</button><p class="muted">メガモン・ほこら等の敵データや特殊な職業制限は未収録。ここでは攻略条件を直接指定します。</p></form><div id="recommendations">${resultHTML()}</div></div>`;$('#conditions').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);target.mode=f.get('mode');['healers','minHp','minSpeed'].forEach(k=>target[k]=Number(f.get(k)));choices.element.forEach(k=>target.weakness[k]=Number(f.get('weak-'+k)));$('#recommendations').innerHTML='<div class="empty">編成を探索しています…</div>';setTimeout(()=>{try{results=WalkEngine.optimize(data,target);$('#recommendations').innerHTML=resultHTML();}catch(err){msg('計算できませんでした。登録データをご確認ください。'+err.message);}},40);}; }
function resultHTML(){if(!results)return '<div class="empty"><h2>次の冒険の編成を。</h2>左の攻略条件を設定して、候補を算出してください。<br><span class="muted">初期データは動作確認用の架空サンプルです。</span></div>';if(!results.teams.length)return `<div class="empty"><h2>条件を満たす候補が見つかりません</h2>${results.missing.length?'キャラ'+results.missing.join('・')+'の職業・武器・HP条件を確認してください。':'所持数・回復役数・最低HPなどを見直してください。'}<p class="muted">探索幅に制限があるため、実際には成立する編成を見つけられない場合があります。</p></div>`;return `<p class="muted">登録値から求めた候補 上位${results.teams.length}件。評価点はダメージ量ではありません。数値が近い候補を比較してください。</p>`+results.teams.map((t,i)=>`<article class="panel result"><div class="row spread"><h2>候補 ${String(i+1).padStart(2,'0')}</h2><div><span class="muted">編成評価点 </span><b class="score">${t.score.toFixed(1)}</b></div></div><span class="pill">回復役 ${t.healers}人</span><div class="members">${t.members.map(m=>`<div class="member"><div class="muted">キャラ${m.job.member} · ${esc(m.job.name)}</div><h3>${esc(m.job.job)} <span class="muted">Lv.${m.job.level}</span></h3><strong>${esc(m.weapon.name)}</strong><p>${m.items.filter(x=>x.slot!=='武器').map(x=>esc(x.name)).join(' / ')||'防具・アクセサリーなし'}</p><p>${m.hearts.map(h=>`枠${h.slot} ${esc(h.name)} ${esc(h.rank)}（×${h.factor}）`).join('<br>')||'こころなし'}</p><div class="muted">HP ${m.s.hp} · すばやさ ${m.s.speed}<br>こころコスト ${m.cost} / ${Number(m.job.cost)+m.bonus}<br>${esc(m.weapon.role)}評価値 ${m.s[m.weapon.role==='回復'?'heal':m.weapon.role==='呪文'?'magic':'attack']} · 属性倍率 ${m.weapon.role==='回復'?'対象外':target.weakness[m.weapon.element]??1}</div><p>評価点 ${m.score.toFixed(1)}：${esc(m.weapon.role)}の登録値${m.weapon.role==='回復'?'':'と敵の属性倍率'}、HP・すばやさを加点。</p></div>`).join('')}</div></article>`).join('');}
function renderData(){const schema=schemas[tab],items=data[tab];$('#view').innerHTML=`<div class="row spread"><div><h2>${schema.label}を登録</h2><p class="muted">職業はキャラごとに複数登録できます。装備とこころはランク・性能の違いごとに登録してください。</p></div><span class="pill">${items.length}件</span></div><details class="panel" open><summary>新しいデータを追加</summary><form id="add"><div class="fields sub">${schema.fields.map(k=>field(k,defaults(k))).join('')}</div><button class="primary">登録する</button></form></details><div class="tablewrap"><table><thead><tr>${schema.fields.map(k=>`<th>${labels[k]}</th>`).join('')}<th>操作</th></tr></thead><tbody>${items.map(x=>`<tr>${schema.fields.map(k=>`<td>${esc(x[k])}</td>`).join('')}<td><button data-edit="${x.id}">編集</button> <button data-delete="${x.id}">削除</button></td></tr>`).join('')}</tbody></table></div>`;$('#add').onsubmit=e=>{e.preventDefault();try{let row=readRow(Object.fromEntries(new FormData(e.target)),tab);data[tab].push({...row,id:uid()});save();msg('登録しました。');renderData();}catch(err){msg(err.message);}};$('#view').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{data[tab]=data[tab].filter(x=>x.id!==b.dataset.delete);save();renderData();});$('#view').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{let item=items.find(x=>x.id===b.dataset.edit);$('#add').innerHTML=`<div class="fields sub">${schema.fields.map(k=>field(k,item[k])).join('')}</div><button class="primary">変更を保存</button> <button type="button" id="cancel">キャンセル</button>`;$('#cancel').onclick=renderData;$('#add').onsubmit=e=>{e.preventDefault();try{Object.assign(item,readRow(Object.fromEntries(new FormData(e.target)),tab));save();renderData();msg('変更を保存しました。');}catch(err){msg(err.message);}};$('#add').scrollIntoView({behavior:'smooth'});});}
function defaults(k){return ({member:1,name:'',job:'',level:1,role:'物理',cost:400,colors:'虹/赤/黄/青',colorBonus:1.2,count:1,minLevel:1,jobs:'*',rank:'S',slot:'武器',element:'無',color:'赤'})[k]??0;}
function readRow(obj,type){const row={};for(const k of schemas[type].fields){let v=obj[k];if(v===undefined||String(v).trim()==='')throw Error(labels[k]+'を入力してください。');if(numeric.has(k)){v=Number(v);if(!Number.isFinite(v)||v<0)throw Error(labels[k]+'は0以上の数値にしてください。');if(['member','level','cost','count','minLevel','costBonus'].includes(k)&&!Number.isInteger(v))throw Error(labels[k]+'は整数にしてください。');}else v=String(v).trim();if(choices[k]&&!choices[k].includes(v))throw Error(labels[k]+'の値を確認してください。');row[k]=v;}if(type==='jobs'){if(row.member<1||row.member>4||row.level<1)throw Error('キャラ番号は1〜4、レベルは1以上です。');if(row.colorBonus<1||row.colorBonus>2)throw Error('色一致倍率は1〜2の範囲です。');const slots=row.colors.split('/');if(slots.length!==4||slots.some(s=>s!=='虹'&&s.split('+').some(c=>!choices.color.includes(c))))throw Error('枠色は4枠を / で区切ります。例：虹/赤+黄/青/紫');}return row;}
function download(name,text,type){const url=URL.createObjectURL(new Blob(['\ufeff',text],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvParse(text){let rows=[],row=[],v='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else if(!quoted&&v.length)throw Error('CSVの引用符が不正です。');else quoted=!quoted;}else if(!quoted&&(c===','||c==='\n')){row.push(v);v='';if(c==='\n'){rows.push(row);row=[];}}else if(c!=='\r'||quoted)v+=c;}if(quoted)throw Error('CSVの引用符が閉じていません。');if(v||row.length){row.push(v);rows.push(row);}return rows.filter(r=>r.some(c=>c.trim()));}
function renderTransfer(){ $('#view').innerHTML=`<h2>データをまとめて登録</h2><p>種類ごとのCSVを取り込めます。まず現在のCSVを書き出すと、列名と記入例を確認できます。</p><div class="panel stack"><label>対象データ<select id="csvkind">${Object.entries(schemas).map(([k,s])=>`<option value="${k}">${s.label}</option>`).join('')}</select></label><div class="row"><button id="exportcsv">現在のCSVを書き出す</button><input class="file" type="file" id="csvfile" accept=".csv,text/csv" aria-label="CSVファイルを選択"></div><textarea id="csvtext" aria-label="CSV入力欄" placeholder="CSVファイルを選択するか、ヘッダー付きCSVをここに貼り付けてください"></textarea><button id="importcsv" class="primary">CSVを追加登録</button><p class="muted">UTF-8・ヘッダー必須。全行を検証した後に追加します。同じデータの二重取り込みは所持数の二重計上になるため、取り込み前に登録一覧をご確認ください。</p></div><div class="panel sub"><h3>バックアップ</h3><p class="muted">JSONには全キャラ・全所持データを含みます。復元時は現在の全登録データを置き換えます。</p><div class="row"><button id="backup">JSONを書き出す</button><input class="file" id="restore" type="file" accept=".json" aria-label="JSONバックアップから復元"></div></div><details><summary>サンプルを使わずに始める</summary><p>登録データを空にします。先にバックアップを保存してください。</p><button id="clear" class="danger">全登録データを消去</button> <button id="sample">サンプルに戻す</button></details>`;$('#exportcsv').onclick=()=>{const k=$('#csvkind').value;let keys=schemas[k].fields;const q=x=>'"'+String(x??'').replaceAll('"','""')+'"';download(k+'.csv',[keys.join(','),...data[k].map(x=>keys.map(k=>q(x[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8');};$('#csvfile').onchange=async e=>{if(e.target.files[0])$('#csvtext').value=await e.target.files[0].text();};$('#importcsv').onclick=()=>{try{const k=$('#csvkind').value;const rows=csvParse($('#csvtext').value.replace(/^\uFEFF/,''));if(rows.length<2)throw Error('ヘッダーとデータ行を入力してください。');let keys=rows.shift().map(s=>s.trim());if(new Set(keys).size!==keys.length||schemas[k].fields.some(f=>!keys.includes(f)))throw Error('CSVの列名を確認してください。現在のCSVを書き出して列名を確認できます。');const parsed=rows.map((r,i)=>{try{if(r.length!==keys.length)throw Error('列数が一致しません。');return {...readRow(Object.fromEntries(keys.map((k,j)=>[k,r[j]])),k),id:uid()};}catch(e){throw Error((i+2)+'行目：'+e.message);}});data[k].push(...parsed);save();msg(parsed.length+'件を追加しました。');}catch(err){msg(err.message);}};$('#backup').onclick=()=>download('walk-party-backup.json',JSON.stringify(data,null,2),'application/json');$('#restore').onchange=async e=>{try{if(!e.target.files[0])return;let raw=JSON.parse((await e.target.files[0].text()).replace(/^\uFEFF/,'')),next={};for(const k of Object.keys(schemas)){if(!Array.isArray(raw[k]))throw Error('バックアップ形式が違います。');next[k]=raw[k].map(x=>({...readRow(x,k),id:uid()}));}if(!confirm('現在の全登録データをバックアップの内容で置き換えますか？'))return;data=next;save();renderTransfer();msg('復元しました。');}catch(err){msg('復元できませんでした：'+err.message);}};$('#clear').onclick=()=>{if(confirm('全キャラ・装備・こころを削除しますか？')){data={jobs:[],gear:[],hearts:[]};save();render();msg('登録データを消去しました。');}};$('#sample').onclick=()=>{if(confirm('現在のデータをサンプルで置き換えますか？')){data=sample();save();render();msg('サンプルを読み込みました。');}};}
function renderHelp(){$('#view').innerHTML=`<article class="panel"><h2>評価のしくみと試作版の範囲</h2><h3>目的に合わせて評価</h3><p>各キャラの評価点 ＝ 役割に応じた評価値 × 敵の属性倍率 ＋ HP × HP係数 ＋ すばやさ × すばやさ係数。回復役には属性倍率を適用しません。編成評価点は4人分の合計です。</p><ul><li>ボス：HP係数 0.15、すばやさ係数 0.08</li><li>周回：HP係数 0.03、すばやさ係数 0.5</li><li>耐久：HP係数 0.6、すばやさ係数 0.03</li></ul><h3>入力する数値</h3><p>職業には、そのキャラ・職業・レベルでの装備とこころを外した基礎値を登録します。永続効果などを含める場合は、基礎値に反映してください。レベル自体の加点や基礎値の自動推定は行わず、装備の必要レベルの判定に使います。装備の攻撃・呪文・回復評価値は手動で同じ尺度にそろえる必要があります。スキル倍率や回復上限は自動計算しません。</p><h3>所持数とこころの条件</h3><p>装備とこころの所持数を4人で共有し、各部位1個、こころ4枠までに制限します。同じ名前のこころは1キャラに重複させません。枠色が一致すると、入力した色一致倍率でこころの基礎値を補正し、小数点以下を切り捨てます。虹枠も同じ倍率として扱います。白色等の例外は再現していないため、該当する場合は入力値で補正してください。最大コスト加算の合計を許容コストに加えます。</p><h3>探索は近似です</h3><p>装備候補を各段階24件、こころ候補を100件、職業と武器ごとに100件に絞り、編成は回復役人数ごとに120件を残すビーム探索です。キャラ1から順番に割り当てるため順序の影響があり、全組み合わせの最適解は保証しません。</p><h3>まだ考慮していないもの</h3><p>敵の守備力、種族、状態異常、属性耐性以外の耐性、スキル倍率・上限、職業固有効果、こころの特殊効果、セット効果、宝珠・心珠・こころ道、MP消費、行動順、戦闘シミュレーション、実際の装備可否、コンテンツ固有の職業制限は未対応です。使用可能職業は装備側で入力してください。アクセサリーは試作では1枠のみです。</p><p class="muted">ゲームのこころ・コストの基本仕様の参照：<a href="https://walk.dragonquest.jp/web/help/" target="_blank" rel="noreferrer">公式ヘルプ</a>。本ツールの評価式・サンプル数値は独自の試作用モデルです。</p></article>`;}
render();
